export const CRASH_TAXONOMY_BY_ID: Record<string, CrashFailureRecord> = Object.fromEntries(
  CRASH_TAXONOMY.map((rec) => [rec.id, rec])
);

export function getCrashTaxonomyForStunt(stuntId: MissionId): CrashFailureRecord[] {
  return CRASH_TAXONOMY.filter((rec) => rec.stuntId === stuntId);
}

export function resolveCrashRecord(type: string, stuntId?: MissionId): CrashFailureRecord {
  if (CRASH_TAXONOMY_BY_ID[type]) {
    return CRASH_TAXONOMY_BY_ID[type];
  }
  if (stuntId) {
    const list = getCrashTaxonomyForStunt(stuntId);
    if (list.length > 0) return list[0];
  }
  return CRASH_TAXONOMY[0];
}
